package com.example.rag.controller;
import org.springframework.web.bind.annotation.*; import org.springframework.jdbc.core.JdbcTemplate; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController { private final JdbcTemplate jdbc; public DashboardController(JdbcTemplate jdbc){this.jdbc=jdbc;} @GetMapping("/summary") public Map<String,Object> summary(){int kb=jdbc.queryForObject("select count(*) from kb_knowledge_base where deleted=false",Integer.class);int docs=jdbc.queryForObject("select count(*) from kb_document where deleted=false",Integer.class);int qa=jdbc.queryForObject("select count(*) from kb_qa_record where created_at::date=current_date",Integer.class);List<Map<String,Object>> recent=jdbc.queryForList("select id,name,category,visibility,updated_at as updatedAt,(select count(*) from kb_document d where d.kb_id=k.id and d.deleted=false) as docs from kb_knowledge_base k where deleted=false order by updated_at desc limit 3");List<Map<String,Object>> todos=List.of(Map.of("title","2026 年度目标确认","type","人事","time","今天 18:00 前","color","orange"),Map.of("title","华东区域差旅报销单","type","财务","time","明天 12:00 前","color","blue"),Map.of("title","办公用品领用审批","type","行政","time","3 月 20 日","color","purple"));return Map.of("knowledgeBaseCount",kb,"documentCount",docs,"todayQaCount",qa,"hitRate",92,"pendingCount",todos.size(),"recentKbs",recent,"todos",todos); } }
